package org.transittr.tests;
import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.widget.*;import android.view.*;import java.lang.reflect.*;
public class Smoke extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private String dump(View v){String s=v instanceof TextView?((TextView)v).getText().toString():"";if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)s+="\n"+dump(g.getChildAt(i));}return s;}
 private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 private Object field(Activity a,String name)throws Exception{Field f=a.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(a);}
 private int peakPssKB=0;
 private synchronized void sample(){android.os.Debug.MemoryInfo m=new android.os.Debug.MemoryInfo();android.os.Debug.getMemoryInfo(m);peakPssKB=Math.max(peakPssKB,m.getTotalPss());check(peakPssKB<195312,"PSS under 200 MB; actual KiB="+peakPssKB);}
 public void onStart(){Bundle result=new Bundle();try{final Activity a=startActivitySync(new Intent().setClassName("org.transittr","org.transittr.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();sample();final EditText search=(EditText)field(a,"search");final Spinner city=(Spinner)field(a,"city");final ListView list=(ListView)field(a,"list");check(search!=null&&list!=null,"UI initialized: "+dump(a.getWindow().getDecorView()));runOnMainSync(new Runnable(){public void run(){city.setSelection(1);search.setText("M2");}});Thread.sleep(800);waitForIdleSync();sample();check(list.getHeight()>0,"list visible on portrait; root="+a.getWindow().getDecorView().getHeight()+", list="+list.getHeight()+", display="+a.getResources().getDisplayMetrics().widthPixels+"x"+a.getResources().getDisplayMetrics().heightPixels);check(list.getAdapter().getCount()>0,"M2 search returned rows");check(list.getAdapter().getItem(0).toString().startsWith("M2 ·"),"exact route ranked first");
  final Method near=a.getClass().getDeclaredMethod("near",Double.TYPE,Double.TYPE);near.setAccessible(true);runOnMainSync(new Runnable(){public void run(){try{near.invoke(a,41.0385,28.9858);}catch(Exception e){throw new RuntimeException(e);}}});waitForIdleSync();sample();check(list.getAdapter().getCount()>0&&list.getAdapter().getCount()<=30,"offline nearby query");
  final SQLiteDatabase db=(SQLiteDatabase)field(a,"db");Cursor c=db.rawQuery("SELECT s.id FROM stops s JOIN sources x ON x.id=s.source WHERE s.name='Konak' AND x.name LIKE '%/ Metro' LIMIT 1",null);check(c.moveToFirst(),"Konak exists");int id=c.getInt(0);c.close();Method schedule=a.getClass().getDeclaredMethod("schedule",Integer.TYPE);schedule.setAccessible(true);String times=(String)schedule.invoke(a,id);check(times.contains("Planlı kalkışlar"),"native timetable query");
  runOnMainSync(new Runnable(){public void run(){city.setSelection(6);search.setText("");}});Thread.sleep(800);waitForIdleSync();sample();check(list.getAdapter().getCount()>0,"Konya catalog screen");Class<?> ego=a.getClassLoader().loadClass("org.transittr.EgoLocal");Method parse=ego.getMethod("parse",String.class,String.class);String fixture="<div class=\"bus-list\"><div class=\"bus-card\"><div class=\"route-badge\">591-1</div><div class=\"route-title\">KORU METRO</div><div class=\"eta-mins\">13dk 9sn</div></div><center>04.11.2026 19:16:44</center></div>";for(int n=0;n<100;n++){check(((String)parse.invoke(null,fixture,"10001")).contains("591-1"),"local result parser");sample();}int offlinePeak=peakPssKB;peakPssKB=0;final java.util.concurrent.atomic.AtomicBoolean measuring=new java.util.concurrent.atomic.AtomicBoolean(true);Thread sampler=new Thread(new Runnable(){public void run(){while(measuring.get()){sample();try{Thread.sleep(200);}catch(InterruptedException ignored){break;}}}});sampler.start();String liveStatus;long began=System.currentTimeMillis();try{String live=(String)a.getClassLoader().loadClass("org.transittr.EgoMobile").getMethod("query",String.class).invoke(null,"10001");liveStatus=live.contains("Alınma zamanı:")?"SUCCESS_SOURCE_RESULT":"UNVERIFIED_RESPONSE";}catch(Exception failure){Throwable cause=failure.getCause()==null?failure:failure.getCause();liveStatus="UNVERIFIED: "+cause.getClass().getName()+" "+cause.getMessage();}finally{sample();measuring.set(false);sampler.interrupt();sampler.join(2000);}result.putString("stream","OFFLINE_PEAK_PSS_KIB="+offlinePeak+"; EGO_REQUEST_SAMPLED_PEAK_PSS_KIB="+peakPssKB+"; EGO_REQUEST_MS="+(System.currentTimeMillis()-began)+"; EGO_STATUS="+liveStatus+"\nPEAK_SAMPLED_PSS_KIB="+Math.max(offlinePeak,peakPssKB)+"; 200 MB assertion PASS. Samples cover launch, offline screens, 100 local parser calls and one real EGO HTTPS attempt. Successful live data remains unverified; this run covers only this emulator.\nPASS Android API "+android.os.Build.VERSION.SDK_INT+": activity launch, database copy/open, exact M2 search, offline nearby, native timetable SQL, Konya catalog\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable t){java.io.StringWriter out=new java.io.StringWriter();t.printStackTrace(new java.io.PrintWriter(out));result.putString("stream","FAIL: "+out.toString());finish(Activity.RESULT_CANCELED,result);}}
}
